  "difficulty": "Média",
  "statement": "Uma seleção de futebol convocou 23 jogadores, sendo 2 para cada uma das 10 posições de linha, e 3 para o gol. Um dos jogadores de linha convocado pode jogar em duas posições de linha diferentes (a posição para a qual foi convocado e mais uma outra posição), e todos os demais convocados jogam apenas em sua respectiva posição de convocação, incluindo-se os goleiros. Respeitando-se a posição que cada jogador pode jogar, o total de escalações distintas que essa seleção pode fazer é igual a",
