    "Incorreta (C). Esta opção não condiz com as exigências teóricas ou matemáticas da questão. A resposta correta e comprovada pelos fundamentos da matéria é a alternativa D.",
    "Correta (D). Conforme a resolução: Em 15 minutos: $\\Delta V = 120\\ \\mathrm{L} = 120 \\times 10^{-3}\\ \\mathrm{m^3} = 0{,}12\\ \\mathrm{m^3}$. Intervalo de tempo: $\\Delta t = 15 \\times 60 = 900\\ \\mathrm{s}$. A vazão volumétrica é dada por: $Z = \\frac{\\Delta V}{\\Delta t} = \\frac{0{,}12\\ \\mathrm{m^3}}{900\\ \\mathrm{s}} \\approx 1{,}33 \\times 10^{-4}\\ \\mathrm{m^3/s}$.",
