  "detail": "Brasil Colonial",
  "difficulty": "Média",
  "statement": "Leia o texto para responder às questões 44 e 45.\n\nÉ o comércio que os interessa [aos europeus que vêm para a América, a partir do século XV], e daí o relativo desprezo por este território primitivo e vazio que é a América; e inversamente, o prestígio do Oriente, onde não faltava objeto para atividades mercantis. [...]\n\nOs problemas de novo sistema de colonização, envolvendo a ocupação de territórios quase desertos e primitivos, terão feição variada, dependendo em cada caso das circunstâncias particulares com que se apresentam. A primeira delas será a natureza dos gêneros aproveitáveis que cada um daqueles territórios proporcionará.\n\n(Caio Prado Júnior. Formação do Brasil contemporâneo, 1987.)\n\nA afirmação de que as primeiras preocupações de explorar bens da colônia variaram de acordo com “a natureza dos gêneros aproveitáveis que cada um daqueles territórios proporcionará” pode ser exemplificada, no caso do Brasil,",
  "blockTypes": [
    "prose",
    "prose",
    "prose",
    "prose",
    "command"
  ],
  "alternatives": [
    "pela agricultura exportadora, estabelecida no Sudeste.",
    "pelo extrativismo vegetal, nas regiões costeiras da colônia.",
    "pela agricultura de subsistência, estabelecida em todo o litoral.",
    "pela utilização imediata de mão de obra escrava, vinda da África.",
    "pelo extrativismo mineral, nas áreas centrais da colônia."
  ],
  "answer": "B",
  "annulled": false,
  "annulmentNoValidAnswer": false,
  "resolution": [
    "Antes de se tornar grande produtor de açúcar, graças à lavoura de plantation, o Brasil já oferecia, aos comerciantes lusos, um produto nativo de grande aceitação na Europa e que proporcionava bons lucros: o pau-brasil, árvore produtora de um corante ver me - lho utilizado nas manufaturas têxteis da época. Uma variante dessa madeira já era conhecida dos europeus desde o século XIII, fazendo parte das importações de produtos orientais."
  ],
  "resolutionMatched": true,
