    "a guerra ideológica, de afirmação dos valores do comunismo, e a guerra religiosa, de contestação ao judaísmo e ao islamismo.",
    "a guerra industrial, que buscava ultrapassar a produção fabril britânica, e a guerra comercial, na luta pelo controle do mercado consumidor norte-americano.",
    "a guerra diplomática, desenvolvida dentro da Liga das Nações, e a guerra colonial, contra as possessões francesas e britânicas no norte da África.",
    "a guerra de expansão territorial, levada adiante por seu aparato militar, e a guerra étnica, de perseguição sistemática a judeus, ciganos e negros."
