  "statement": "A figura representa o esquema de uma pilha formada com placas de níquel e zinco mergulhadas em soluções contendo seus respectivos íons a 25 ºC.\n\nDados potenciais-padrão de redução:\n$\\text{Zn}^{2+}\\text{ (aq)} + 2\\text{e}^- \\rightarrow \\text{Zn (s)} \\quad E^\\circ = -0{,}76\\text{ V}$\n$\\text{Ni}^{2+}\\text{ (aq)} + 2\\text{e}^- \\rightarrow \\text{Ni (s)} \\quad E^\\circ = -0{,}23\\text{ V}$",
