  "n": 63,
  "subject": "Literatura",
  "content": "Poesia e linguagem poética",
  "detail": "Poesia e linguagem poética",
  "difficulty": "Média",
  "statement": "Leia o poema de Fernando Pessoa para responder às questões de números 61 a 63.\n\nAutopsicografia\n\nO poeta é um fingidor. Finge tão completamente Que chega a fingir que é dor A dor que deveras sente.\n\nE os que leem o que escreve, Na dor lida sentem bem, Não as duas que ele teve, Mas só a que eles não têm.\n\nE assim nas calhas de roda Gira, a entreter a razão, Esse comboio de corda Que se chama o coração.\n\n(Obra poética, 1984.)\n\nSe for considerada a temática predominante nas obras de Fernando Pessoa (ele-mesmo, ortônimo) e nas obras de seus heterônimos mais conhecidos, é correto afirmar que o poema “Autopsicografia” pode ser atribuído a",
