    "Correta (B). Conforme a resolução: A ingestão de frutas e vegetais deve ser incluída na alimentação saudável. No texto: “Don’t let that stop you from including more fruits and veggies in your diet, though. Even if they don’t directly help you lose weight, these foods still provide a number of health benefits.”",
