  "detail": "Ecologia e relações entre seres vivos",
  "difficulty": "Média",
  "statement": "Um ecossistema é composto tanto por fatores bióticos (comunidade ou biota) como por fatores abióticos (variáveis físicas e químicas do ambiente). Nos ecossistemas tais fatores estão fortemente relacionados, proporcionando diversas interações entre os seres vivos e o ambiente físico.\n\nUm impacto ambiental é, essencialmente, uma alteração relevante nos componentes bióticos ou abióticos dos ecossistemas.",
